/** Generated by scripts/export-car-svg.cjs — coordinates are projected world units.
 * All colour/drivetrain/day-night variants of a body use the SAME frame. */
export const CAR_ASSET_FRAMES = {
  "hatch": {
    "x": -3.3,
    "y": -26.514,
    "width": 51.845,
    "height": 35.199,
    "nominalMetres": 4.2
  },
  "saloon": {
    "x": -3.3,
    "y": -27.966,
    "width": 55.136,
    "height": 36.714,
    "nominalMetres": 4.7
  },
  "fastback": {
    "x": -3.3,
    "y": -27.718,
    "width": 55.33,
    "height": 36.508,
    "nominalMetres": 4.7
  },
  "crossover": {
    "x": -3.3,
    "y": -28.866,
    "width": 55.312,
    "height": 37.782,
    "nominalMetres": 4.6
  },
  "coupe_suv": {
    "x": -3.3,
    "y": -29.484,
    "width": 56.9,
    "height": 38.484,
    "nominalMetres": 4.8
  },
  "large_suv": {
    "x": -3.3,
    "y": -31.28,
    "width": 58.488,
    "height": 40.364,
    "nominalMetres": 5
  }
} as const;

export type CarAssetBody = keyof typeof CAR_ASSET_FRAMES;
export type CarVisualStyle = 'modern' | 'retro';
export type CarAssetColour = 'midnight' | 'white' | 'silver' | 'black' | 'red' | 'blue';

/** Compatible with the colour swatches in HouseIllustration. */
const COLOUR_KEYS: Record<string, CarAssetColour> = {
  "#34404f": "midnight",
  "#eceeef": "white",
  "#9aa3ad": "silver",
  "#1d1f22": "black",
  "#8c2b2b": "red",
  "#2f5a7a": "blue"
};

export function carAssetPath(vehicle: { body?: string; colour?: string; ev?: boolean }, night: boolean, style: CarVisualStyle = 'modern'): string {
  const body = vehicle.body === 'suv' ? 'crossover' : (vehicle.body || 'hatch');
  const safeBody = Object.prototype.hasOwnProperty.call(CAR_ASSET_FRAMES,body) ? body : 'hatch';
  const colour = COLOUR_KEYS[(vehicle.colour || '#34404f').toLowerCase()] || 'midnight';
  return `/cars/${style === 'retro' ? 'retro' : 'modern'}/${safeBody}-${colour}${vehicle.ev === false ? '' : '-ev'}${night ? '-night' : ''}.webp`;
}
